import itertools

def solve():
    n = 6
    k = 2
    all_triples = list(itertools.combinations(range(n), 3))
    all_pairs = list(itertools.combinations(range(n), 2))

    designs = []
    for triples in itertools.combinations(all_triples, 10):
        # check if it's a (6,3,2) design
        is_design = True
        for pair in all_pairs:
            count = 0
            for triple in triples:
                if pair[0] in triple and pair[1] in triple:
                    count += 1
            if count != k:
                is_design = False
                break
        if is_design:
            designs.append(triples)

    print(f"Found {len(designs)} designs")

    for design in designs:
        min_mono = float('inf')
        for coloring in itertools.product([0, 1], repeat=n):
            mono_count = 0
            for triple in design:
                if coloring[triple[0]] == coloring[triple[1]] == coloring[triple[2]]:
                    mono_count += 1
            if mono_count < min_mono:
                min_mono = mono_count
        if min_mono >= 2:
            print(f"Design found with min_mono {min_mono}")
            return True
    return False

print(solve())
